  ('NO-3', 'bodo', 'it', 'Bodø', 'Capoluogo del Nordland, nella regione di Salten: è la porta delle Lofoten, con il traghetto per Moskenes, l''aeroporto e il capolinea della ferrovia del Nordland.', 'In aereo, in treno (capolinea della linea del Nordland) o in auto; dal porto partono i traghetti per le Lofoten (vedi Trasporti via mare).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'kjerringoy', 'it', 'Kjerringøy, antico emporio', 'Museo all''aperto in un antico emporio commerciale sulla costa a nord di Bodø; fa parte del museo del Nordland.', 'In auto da Bodø verso nord; lungo la strada c''è un breve traghetto, con orari da verificare.', 'Apertura stagionale: da verificare sul sito del museo', null, null, null, null, null),
  ('NO-3', 'luftfartsmuseum', 'it', 'Museo norvegese dell''aviazione', 'Museo nazionale dell''aviazione, aperto nel 1994: è il più grande dei paesi nordici (circa 10.000 m²), in un edificio a forma di elica, con aerei civili e militari.', 'A Bodø, in città.', 'Tutto l''anno; orari da verificare sul sito del museo', null, null, null, null, null),
  ('NO-3', 'keiservarden', 'it', 'Keiservarden', 'Altopiano panoramico a 366 m sopra Bodø, sul colle Veten. Il nome ricorda l''imperatore tedesco Guglielmo II che, secondo la tradizione, vi salì nel 1899.', 'A piedi su sentiero dai dintorni di Bodø; punto di partenza e tempi da verificare.', 'Estate e inizio autunno; con neve o ghiaccio il sentiero cambia', null, null, null, null, null),
  ('NO-3', 'moskenes', 'it', 'Moskenes', 'Villaggio sull''isola di Moskenesøya, subito a nord di Sørvågen, dove attracca il traghetto da Bodø. La chiesa bianca in legno è lungo la E10.', 'Traghetto da Bodø (vedi Trasporti via mare) oppure in auto sulla E10.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'sorvagen', 'it', 'Sørvågen', 'Villaggio di pescatori sull''isola di Moskenesøya, tra Moskenes e Å, lungo la E10.', 'Lungo la E10, la strada delle Lofoten, poco prima di Å.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'reinebringen', 'it', 'Reinebringen', 'Cima di 484 m sopra Reine, tra le più salite della Norvegia. Si sale su una scalinata in pietra, ripida e faticosa, fino a una vista sul Reinefjord.', 'A piedi da Reine; punto di partenza e parcheggio da verificare.', 'Estate; in autunno, inverno e primavera la salita è sconsigliata per il rischio di sassi e neve', 'Salita ripida e impegnativa, con incidenti e soccorsi in passato: con bambini di 5 e 8 anni va valutata con molta prudenza. L''area di sosta Reinehalsen, ai piedi del monte, dà una bella vista senza salire.', null, null, null, null),
  ('NO-3', 'kvalvika', 'it', 'Kvalvika', 'Baia con due spiagge di sabbia sul lato esterno di Moskenesøya, chiusa tra i monti Ryten e Kjerringa. Non ci arriva nessuna strada.', 'Solo a piedi su sentiero (circa 2 km dal Torsfjorden); punto di partenza e parcheggio da verificare.', 'Estate', 'Il sentiero ha tratti sassosi: da valutare con il bambino di 5 anni.', null, null, null, null),
  ('NO-3', 'ryten', 'it', 'Ryten', 'Monte sull''isola di Moskenesøya, a nord della baia di Kvalvika: dalla cima si vede la spiaggia dall''alto.', 'A piedi su sentiero dai dintorni di Fredvang; punto di partenza, dislivello e tempi da verificare.', 'Estate', 'Escursione di montagna con tratti esposti in cima: da valutare con bambini piccoli.', null, null, null, null),
  ('NO-3', 'fredvang', 'it', 'Fredvang', 'Villaggio di pescatori sull''isola di Moskenesøya, collegato a Flakstadøya da due ponti a sbalzo (Fredvangbruene). È il punto d''accesso ai sentieri per Kvalvika e Ryten.', 'Deviazione dalla E10 attraverso i due ponti di Fredvang.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'ramberg', 'it', 'Ramberg e la sua spiaggia', 'Villaggio dell''isola di Flakstadøya con una lunga spiaggia di sabbia chiara rivolta a nord. L''area di sosta della strada turistica ha una passerella in legno che porta alla spiaggia.', 'Lungo la E10, la strada delle Lofoten: la spiaggia è accanto alla strada.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'flakstad-kirke', 'it', 'Chiesa di Flakstad', 'Chiesa rossa in legno a pianta a croce, costruita nel 1780 nel villaggio di Flakstad; ha circa 300 posti.', 'Poco fuori dalla E10, tra Ramberg e Skagsanden.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-3', 'skagsanden', 'it', 'Spiaggia di Skagsanden', 'Spiaggia di sabbia sull''isola di Flakstadøya, accanto al villaggio di Flakstad, lungo la strada turistica delle Lofoten.', 'Lungo la E10, la strada delle Lofoten: la spiaggia è accanto alla strada.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'vikten', 'it', 'Vikten', 'Piccolo villaggio sulla costa nord di Flakstadøya, alla fine di una deviazione della strada turistica; c''è un laboratorio di artigianato con lavorazione del vetro.', 'Deviazione dalla E10 (strada 811), a fondo cieco.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'ballstad', 'it', 'Ballstad', 'Uno dei più grandi villaggi di pescatori delle Lofoten, su una piccola isola all''estremità sud-ovest di Vestvågøya, alla bocca del Buksnesfjorden.', 'Deviazione dalla E10 a sud di Leknes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'leknes', 'it', 'Leknes', 'Cittadina al centro di Vestvågøya e capoluogo del comune più popoloso delle Lofoten: negozi e servizi; c''è un piccolo aeroporto.', 'Lungo la E10, la strada delle Lofoten.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'uttakleiv', 'it', 'Spiaggia di Uttakleiv', 'Spiaggia sul lato esterno di Vestvågøya, in fondo a una delle deviazioni della strada turistica delle Lofoten.', 'Deviazione dalla E10 a nord di Leknes, passando per Haukland; strada a fondo cieco.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'unstad', 'it', 'Unstad', 'Piccolo borgo in fondo alla baia di Unstadvika, sul lato esterno di Vestvågøya, circondato da monti di 300–650 m. La spiaggia è nota per il surf.', 'Deviazione dalla E10 (strada 992), a fondo cieco, con una galleria.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'eggum', 'it', 'Eggum', 'Villaggio di pescatori sulla costa nord di Vestvågøya. Accanto ci sono una riserva naturale e un''area di sosta a forma di anfiteatro rivolta all''oceano aperto.', 'Deviazione dalla E10 a Bøstad (strada 994, circa 10 km).', 'Estate; molti vengono qui per il sole di mezzanotte (fino a metà luglio circa: ad agosto il sole tramonta)', null, null, null, null, null),
  ('NO-3', 'borg-lofoten', 'it', 'Borg (Bøstad)', 'Villaggio lungo la E10 al centro di Vestvågøya, accanto alla frazione di Borg con il museo vichingo Lofotr e la chiesa di Borge.', 'Lungo la E10, la strada delle Lofoten.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'stamsund', 'it', 'Stamsund', 'Villaggio di pescatori sul lato sud di Vestvågøya, affacciato sul Vestfjorden, a circa 12 km da Leknes. È uno scalo della rotta costiera.', 'Deviazione dalla E10 da Leknes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'gimsoy', 'it', 'Gimsøya', 'Isola tra Austvågøya e Vestvågøya, attraversata dalla E10 con due ponti. Sul lato nord ci sono spiagge e una piccola chiesa.', 'Lungo la E10, la strada delle Lofoten; il giro dell''isola è una deviazione.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'kabelvag', 'it', 'Kabelvåg', 'Villaggio sulla costa sud di Austvågøya, a circa 5 km da Svolvær. Nella vicina Storvågan ci sono l''acquario, il museo delle Lofoten e la galleria Espolin.', 'Lungo la E10, la strada delle Lofoten, a sud-ovest di Svolvær.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'lofotakvariet', 'it', 'Acquario delle Lofoten', 'Acquario di acqua salata a Storvågan, vicino a Kabelvåg, qui dal 1989: vasche con la vita marina delle Lofoten e bacini per foche e lontre.', 'A Storvågan, poco fuori dalla E10 vicino a Kabelvåg.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'lofotmuseet', 'it', 'Museo delle Lofoten', 'Museo nell''antico villaggio di pescatori di Storvågan: la casa padronale del 1815, le rorbuer, le rimesse con le barche del Nordland e mostre sulla pesca alle Lofoten.', 'A Storvågan, poco fuori dalla E10 vicino a Kabelvåg.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'galleri-espolin', 'it', 'Galleria Espolin', 'Galleria d''arte a Storvågan, vicino a Kabelvåg, nata nel 1992 per le opere di Kaare Espolin Johnson.', 'A Storvågan, poco fuori dalla E10 vicino a Kabelvåg.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'lofotkatedralen', 'it', 'Chiesa di Vågan («cattedrale delle Lofoten»)', 'Grande chiesa gialla in legno a pianta a croce, costruita nel 1898 a Kabelvåg e detta «cattedrale delle Lofoten».', 'Lungo la E10, la strada delle Lofoten, a Kabelvåg.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-3', 'svolvaergeita', 'it', 'Svolværgeita', 'Pinnacolo di roccia alto 150 m sul fianco del monte Fløyfjellet, sopra Svolvær: è una meta di arrampicata, salita per la prima volta nel 1910.', 'Si vede da Svolvær; la salita è una via di arrampicata.', 'Estate', 'La cima è per arrampicatori con guida: con i bambini si guarda dal basso.', null, null, null, null),
  ('NO-3', 'krigsminnemuseum', 'it', 'Museo della guerra delle Lofoten', 'Museo sulla seconda guerra mondiale a Svolvær, aperto nel 1996, dedicato soprattutto ai fatti delle Lofoten e del nord durante l''occupazione tedesca (1940–1945).', 'A Svolvær, in centro.', 'Orari e giorni di apertura da verificare', 'Temi di guerra: da valutare per i bambini.', null, null, null, null),
  ('NO-3', 'trollfjord', 'it', 'Trollfjord', 'Fiordo lungo 2 km che entra nell''isola di Austvågøya dallo stretto di Raftsundet, con un ingresso stretto e pareti ripide.', 'Solo via mare: escursioni in barca da Svolvær; anche le navi della rotta costiera vi entrano in estate. Orari e prezzi da verificare.', 'Estate', null, null, null, null, null),
  ('NO-3', 'skrova', 'it', 'Skrova', 'Piccola isola con un villaggio di pescatori nel Vestfjorden, a sud di Austvågøya.', 'Solo via mare da Svolvær; collegamento e orari da verificare.', 'Estate', null, null, null, null, null),
  ('NO-3', 'laukvik', 'it', 'Laukvik', 'Villaggio di pescatori sulla costa nord-ovest di Austvågøya, affacciato sul Mare di Norvegia.', 'Deviazione dalla E10 sul lato nord di Austvågøya.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'vaeroy', 'it', 'Værøy', 'Isola e comune delle Lofoten, a sud di Moskenesøya. Il centro è il villaggio di Sørland, intorno al porto.', 'Solo via mare o in aereo; i traghetti partono da Bodø e da Moskenes (vedi Trasporti via mare), orari da verificare.', 'Estate', null, null, null, null, null),
  ('NO-3', 'rost', 'it', 'Røst', 'Piccolo comune insulare all''estremità delle Lofoten: di fatto un grande villaggio di pescatori sull''isola di Røstlandet. Le isole vicine ospitano grandi colonie di uccelli marini.', 'Solo via mare o in aereo; i traghetti partono da Bodø (vedi Trasporti via mare), orari da verificare.', 'Estate', null, null, null, null, null),
  ('NO-3', 'fiskevaersmuseum', 'it', 'Museo norvegese dei villaggi di pescatori', 'Museo dedicato alla pesca norvegese nel villaggio di Å: gli edifici del villaggio, fra cui la fabbrica dell''olio di fegato di merluzzo.', 'A Å, dove finisce la E10.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'torrfiskmuseum', 'it', 'Museo dello stoccafisso delle Lofoten', 'Museo nel villaggio di Å dedicato alla produzione dello stoccafisso, uno dei più antichi prodotti di esportazione della Norvegia.', 'A Å, dove finisce la E10.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'sortland', 'it', 'Sortland', 'Cittadina delle Vesterålen e capoluogo del comune omonimo, sullo stretto di Sortlandsundet; qui ha la base nord la Guardia costiera norvegese.', 'Sulla strada tra le Lofoten e Andøya; è anche uno scalo della rotta costiera.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'stokmarknes', 'it', 'Stokmarknes', 'Cittadina sulla costa nord dell''isola di Hadseløya, capoluogo del comune di Hadsel. Qui è nata la rotta costiera Hurtigruten, e c''è il suo museo.', 'In auto dalle Vesterålen (ponti) o dalle Lofoten con il traghetto Fiskebøl–Melbu; è uno scalo della rotta costiera.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'hurtigrutemuseet', 'it', 'Museo Hurtigruten', 'Museo della rotta costiera a Stokmarknes, dove la linea è nata. Comprende l''ex nave costiera MS Finnmarken, che si visita.', 'A Stokmarknes, in centro.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'melbu', 'it', 'Melbu', 'Villaggio sull''isola di Hadseløya, sulla riva nord dell''Hadselfjorden. Da qui parte il traghetto per Fiskebøl, verso le Lofoten.', 'Traghetto da Fiskebøl (vedi Trasporti via mare) o in auto da Stokmarknes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'nyksund', 'it', 'Nyksund', 'Villaggio di pescatori isolato sulla costa nord dell''isola di Langøya, nelle Vesterålen. Si raggiunge su strada solo da sud.', 'In auto da Myre; ultimo tratto su strada stretta, da verificare.', 'Estate', null, null, null, null, null),
  ('NO-3', 'sto', 'it', 'Stø', 'Villaggio di pescatori sulla punta nord dell''isola di Langøya, nelle Vesterålen, affacciato sul Gavlfjorden.', 'In auto da Myre, a fine strada.', 'Estate', null, null, null, null, null),
  ('NO-3', 'bleik', 'it', 'Bleik', 'Villaggio di pescatori sul lato nord-ovest di Andøya, a circa 10 km da Andenes, con una lunga spiaggia di sabbia chiara e l''isolotto di Bleiksøya di fronte.', 'Sulla strada turistica di Andøya, a sud-ovest di Andenes.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'bleiksoya', 'it', 'Bleiksøya', 'Isolotto disabitato e riserva naturale davanti a Bleik: una piramide ripida con pendii erbosi e scogliere, importante per gli uccelli marini.', 'Si guarda da terra (da Bleik o dall''area di sosta Kleivodden) o in barca; escursioni da verificare.', 'Estate, nella stagione dei nidi', null, null, null, null, null),
  ('NO-3', 'andenes-fyr', 'it', 'Faro di Andenes', 'Faro costiero del 1859 nel villaggio di Andenes, all''estremità nord di Andøya; è un edificio protetto dal 1999.', 'Ad Andenes, vicino al porto.', 'Visite all''interno da verificare', null, null, null, null, null),
  ('NO-3', 'spaceship-aurora', 'it', 'Andøya Space (centro spaziale)', 'Base di lancio per razzi sull''isola di Andøya, attiva dal 1962: da qui sono partiti oltre 1.200 razzi sonda. Accanto c''è un centro per i visitatori.', 'Sulla strada tra Andenes e Bleik.', 'Apertura del centro visitatori da verificare', null, null, null, null, null),
  ('NO-3', 'moysalen', 'it', 'Parco nazionale Møysalen', 'Parco nazionale sull''isola di Hinnøya, nato nel 2003 per proteggere un paesaggio alpino costiero intatto, con cime che escono dal mare e dai fiordi. Il punto più alto è il Møysalen, 1.262 m.', 'Accessi a piedi o in barca; punti di partenza da verificare sul sito dei parchi nazionali.', 'Estate', 'Terreno di alta montagna: con i bambini solo brevi passeggiate ai margini.', null, null, null, null),
  ('NO-3', 'harstad', 'it', 'Harstad', 'Seconda città del Troms per abitanti, in gran parte sull''isola di Hinnøya. Sulla penisola di Trondenes ci sono la chiesa medievale e il centro storico.', 'In auto dalla E10; aeroporto di Harstad/Narvik (Evenes); è uno scalo della rotta costiera.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'trondenes-kirke', 'it', 'Chiesa di Trondenes', 'La chiesa medievale in pietra più a nord della Norvegia, al margine nord di Harstad.', 'A Trondenes, pochi chilometri a nord del centro di Harstad.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-3', 'trondenes-senter', 'it', 'Centro storico di Trondenes', 'Museo a Trondenes (Harstad) che racconta oltre 2.000 anni di storia della zona, che in età vichinga fu un centro di potere.', 'A Trondenes, accanto alla chiesa medievale.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'narvik', 'it', 'Narvik', 'Città sull''Ofotfjorden, su una penisola tra due fiordi; è il porto della ferrovia del minerale che arriva dalla Svezia.', 'Sulla E6; treni dalla Svezia (linea di Ofoten); aeroporto di Harstad/Narvik (Evenes).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'narvik-krigsmuseum', 'it', 'Museo della guerra di Narvik', 'Museo di storia militare nel centro di Narvik, con circa 2.500 m² di esposizione sulla battaglia di Narvik del 1940 e sul nord della Norvegia durante la seconda guerra mondiale.', 'A Narvik, in centro.', 'Orari e giorni di apertura da verificare', 'Temi di guerra: da valutare per i bambini.', null, null, null, null),
  ('NO-3', 'ofotbanen', 'it', 'Ferrovia di Ofoten', 'Linea ferroviaria di 43 km dal porto di Narvik al confine svedese di Riksgränsen, dove prosegue come linea del minerale verso Kiruna e Luleå. Sale dal fiordo alla montagna.', 'Treni dalla stazione di Narvik; orari e biglietti da verificare.', 'Tutto l''anno', null, null, null, null, null),
  ('NO-3', 'gryllefjord', 'it', 'Gryllefjord', 'Villaggio di pescatori sulla costa ovest di Senja, lungo il fiordo omonimo. Qui arriva il traghetto estivo da Andenes e comincia la strada turistica di Senja.', 'Traghetto estivo da Andenes (vedi Trasporti via mare) oppure strada 86 da Finnsnes.', 'Estate (il traghetto per Andenes è stagionale)', null, null, null, null, null),
  ('NO-3', 'torsken', 'it', 'Torsken', 'Villaggio sulla costa ovest di Senja, con una chiesa in legno.', 'Deviazione dalla strada 86 vicino a Gryllefjord.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'hamn-i-senja', 'it', 'Hamn i Senja', 'Antico emporio e oggi meta turistica sulla costa di Senja, affacciato sul mare aperto davanti alle isolette del Bergsfjorden.', 'Sulla strada 86, lungo la strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'skaland', 'it', 'Skaland', 'Villaggio sulla riva del Bergsfjorden, sul lato nord-ovest di Senja, con negozio e scuola; era il capoluogo dell''ex comune di Berg.', 'Lungo la strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'tungeneset', 'it', 'Tungeneset', 'Area di sosta sulla punta tra l''Ersfjorden e lo Steinfjorden: una passerella in larice porta sulle rocce, con la vista sul mare aperto e sulle cime dell''Okshornan.', 'Sulla strada turistica di Senja (strada 862), tra Ersfjord e Skaland.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'okshornan', 'it', 'Okshornan', 'Fila di cime aguzze sull''Ersfjorden, a Senja; la più alta è lo Store Okshornet, 559 m. Si vedono bene dalla strada turistica, soprattutto da Tungeneset.', 'Si guardano dall''area di sosta Tungeneset, sulla strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'ersfjord-senja', 'it', 'Ersfjord (Senja)', 'Borgo in fondo all''Ersfjorden, a Senja, sotto le cime dell''Okshornan, con una spiaggia di sabbia bianca e fine.', 'Sulla strada turistica di Senja (strada 862).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'bergsbotn', 'it', 'Bergsbotn', 'Braccio di fiordo e borgo a Senja, circa 5 km a est di Skaland. Sulla strada turistica una piattaforma lunga 44 m dà la vista sul Bergsfjorden e sulle cime intorno.', 'Sulla strada turistica di Senja (strada 862).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'mefjordvaer', 'it', 'Mefjordvær', 'Villaggio di pescatori sulla costa nord-ovest di Senja, lungo il Mefjorden, circa 3,5 km oltre Senjahopen, a fine strada.', 'Deviazione dalla strada turistica di Senja (strada 7868).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'senjahopen', 'it', 'Senjahopen', 'Villaggio lungo il Mefjorden, nella parte nord-ovest di Senja: è uno dei più importanti villaggi di pescatori dell''isola.', 'Sulla deviazione per Mefjordvær dalla strada turistica di Senja.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'segla', 'it', 'Segla', 'Monte a forma di vela sopra il villaggio di Fjordgård, a Senja, con una parete che cade a picco sul fiordo.', 'A piedi su sentiero da Fjordgård; dislivello, tempi e punto di partenza da verificare.', 'Estate', 'Salita ripida con una cresta esposta in cima: non adatta a bambini piccoli. Il monte si guarda bene anche da Fjordgård.', null, null, null, null),
  ('NO-3', 'fjordgard', 'it', 'Fjordgård', 'Villaggio nella parte nord di Senja, ai piedi del monte Segla, a circa 4 km da Husøy in linea d''aria.', 'Deviazione dalla strada turistica di Senja, con gallerie.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'husoy', 'it', 'Husøy', 'Villaggio di pescatori che occupa tutta l''isoletta di Husøy, nell''Øyfjorden, davanti alla costa nord-ovest di Senja.', 'Deviazione dalla strada turistica di Senja (strada 7886); l''isola è collegata da una strada su un molo.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'botnhamn', 'it', 'Botnhamn', 'Piccolo villaggio nella parte nord di Senja, sulla riva ovest del fiordo di Stønnesbotn. Da qui parte il traghetto per Brensholmen, verso Tromsø, e comincia la strada turistica di Senja.', 'Traghetto da Brensholmen (vedi Trasporti via mare) oppure in auto da Finnsnes.', 'Estate (traghetto stagionale: da verificare)', null, null, null, null, null),
  ('NO-3', 'finnsnes', 'it', 'Finnsnes', 'Cittadina sulla terraferma e capoluogo del comune di Senja, proprio di fronte all''isola: il ponte sul Gisundet la collega a Senja. Negozi e servizi.', 'Dalla E6 a Bardufoss; battello veloce da Tromsø e da Harstad, e scalo della rotta costiera (da verificare).', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'anderdalen', 'it', 'Parco nazionale Ånderdalen', 'Parco nazionale di 134 km² nel sud di Senja, istituito nel 1970 e ampliato nel 2004: foresta costiera di pini e betulle, paludi e laghi, con sentieri segnati.', 'In auto dal lato sud di Senja; ingressi e parcheggi da verificare.', 'Estate', null, null, null, null, null),
  ('NO-3', 'brensholmen', 'it', 'Brensholmen', 'Borgo di pescatori e contadini all''estremità sud-ovest di Kvaløya, nel comune di Tromsø. Da qui parte il traghetto per Botnhamn, a Senja.', 'In auto da Tromsø attraverso Kvaløya; traghetto da Botnhamn (vedi Trasporti via mare).', 'Estate (traghetto stagionale: da verificare)', null, null, null, null, null),
  ('NO-3', 'sommaroy', 'it', 'Sommarøy', 'Antico villaggio di pescatori su un gruppo di isolette a circa 36 km a ovest di Tromsø, molto visitato per le spiagge di sabbia bianca e il paesaggio.', 'In auto da Tromsø attraverso Kvaløya; un ponte collega le isole. Vicino a Brensholmen.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'kvaloya', 'it', 'Kvaløya', 'L''«isola delle balene», di fronte a Tromsø: con 737 km² è la quinta isola della Norvegia continentale. Fiordi, monti e piccoli borghi; un ponte la collega a Tromsø.', 'In auto da Tromsø dal ponte di Sandnessund.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'ersfjordbotn', 'it', 'Ersfjordbotn', 'Villaggio su un istmo tra l''Ersfjorden e il Kaldfjorden, sull''isola di Kvaløya, a circa 15 km da Tromsø, in fondo a un fiordo chiuso da cime ripide.', 'In auto da Tromsø attraverso Kvaløya.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'ishavskatedralen', 'it', 'Cattedrale dell''Artico', 'Chiesa moderna di Tromsdalen, sul lato est di Tromsø oltre il ponte, con la grande facciata a triangoli bianchi; è una chiesa parrocchiale, non una cattedrale.', 'A Tromsdalen: a piedi o in autobus dal centro di Tromsø, oltre il ponte.', 'Tutto l''anno; orari di visita e concerti da verificare', null, null, null, null, null),
  ('NO-3', 'fjellheisen', 'it', 'Funivia Fjellheisen', 'Funivia di Tromsø: dalla stazione a valle di Tromsdalen sale in circa quattro minuti a Storsteinen, una terrazza a circa 420 m con la vista sulla città e sui fiordi.', 'Stazione a valle a Tromsdalen, oltre il ponte dal centro di Tromsø.', 'Tutto l''anno; orari, biglietti e chiusure per vento da verificare', null, null, null, null, null),
  ('NO-3', 'polarmuseet', 'it', 'Museo polare', 'Museo di Tromsø sulla caccia artica norvegese, sulla scienza e sulle spedizioni polari, aperto nel 1978 in uno degli edifici più antichi della città.', 'A Tromsø, in centro, sul porto.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'tromso-museum', 'it', 'Museo universitario di Tromsø', 'Museo dell''università di Tromsø, fondato nel 1872: è una delle più antiche istituzioni scientifiche del nord della Norvegia, con sezioni su natura e culture del nord.', 'Nella parte sud dell''isola di Tromsøya; in autobus o in auto dal centro.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'botanisk-hage', 'it', 'Giardino botanico artico-alpino', 'Il giardino botanico più a nord del mondo, aperto nel 1994 e curato dal museo universitario di Tromsø: piante artiche e alpine di tutto l''emisfero nord.', 'Accanto al campus dell''università, nella parte nord dell''isola di Tromsøya.', 'Estate (stagione delle fioriture)', null, null, null, null, null),
  ('NO-3', 'tromso-domkirke', 'it', 'Cattedrale di Tromsø', 'Cattedrale luterana nel centro di Tromsø, sede della diocesi del Nord-Hålogaland; è un edificio in legno.', 'A Tromsø, in centro.', 'Apertura per le visite da verificare', null, null, null, null, null),
  ('NO-3', 'vitensenter', 'it', 'Centro della scienza del Nord', 'Centro di scienza per il pubblico nel campus dell''università di Tromsø, con esperimenti da provare; accanto c''è il planetario.', 'Nel campus dell''università, nella parte nord dell''isola di Tromsøya.', 'Orari e giorni di apertura da verificare', null, null, null, null, null),
  ('NO-3', 'lyngsalpene', 'it', 'Alpi di Lyngen', 'Catena di montagne sulla penisola di Lyngen, a est di Tromsø, con cime e ghiacciai sopra i fiordi.', 'In auto da Tromsø; ci sono traghetti sui fiordi lungo il percorso (vedi Trasporti via mare), da verificare.', 'Estate', null, null, null, null, null),
  ('NO-3', 'lyngseidet', 'it', 'Lyngseidet', 'Capoluogo del comune di Lyngen, su un istmo largo circa 3 km tra un braccio dell''Ullsfjorden e il Lyngenfjorden, ai piedi delle Alpi di Lyngen. Negozi e servizi.', 'In auto da Tromsø, con traghetto sull''Ullsfjorden (da verificare) oppure per la E8 e la E6.', 'Tutto l''anno; in estate luce fino a tarda sera', null, null, null, null, null),
  ('NO-3', 'malselvfossen', 'it', 'Cascata Målselvfossen', 'Cascata sul fiume Målselva, nel comune di Målselv, nell''entroterra del Troms.', 'In auto, con una deviazione dalla E6 nella zona di Bardufoss.', 'Estate', null, null, null, null, null);
