insert into public.place_tips (release_id, place_key, lang, position, body, source_label, source_url, checked_at) values
  ('NO-3', 'lofoten', 'it', 0, 'La strada turistica delle Lofoten è lunga 230 km: segue la E10 dal Raftsundet fino a Å, con deviazioni per Grunnfør, Henningsvær, Eggum, Unstad, Utakleiv, Vikten e Nusfjord.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/', '2026-11-10'),
  ('NO-3', 'lofoten', 'it', 1, 'I traghetti non sono obbligati: la E10 collega le isole senza imbarchi. Le alternative via mare indicate sono Bodø–Moskenes, Svolvær–Skutvik, Bognes–Lødingen e Melbu–Fiskebøl.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/', '2026-11-10'),
  ('NO-3', 'lofoten', 'it', 2, 'Nelle aree di sosta i camper non possono svuotare le acque nere: i punti di scarico più vicini sono a Reine, Hamnøy, Ramberg, Leknes, Lyngvær, Svolvær, Austnesfjorden e Torvdalshalsen.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/', '2026-11-10'),
  ('NO-3', 'andenes', 'it', 0, 'La strada turistica di Andøya è lunga 58 km e segue il lato esterno dell''isola tra Andenes e Bjørnskinn.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/andoya/', '2026-11-10'),
  ('NO-3', 'andenes', 'it', 1, 'Il traghetto Andenes–Gryllefjord, che collega con Senja, è in servizio solo nella stagione estiva.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/andoya/', '2026-11-10'),
  ('NO-3', 'andenes', 'it', 2, 'A Børvågen la strada può restare chiusa fino a 8 ore durante le attività della base spaziale di Andøya: da controllare prima di partire.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/andoya/', '2026-11-10'),
  ('NO-3', 'senja', 'it', 0, 'La strada turistica di Senja è lunga 102 km, tra Botnhamn e Gryllefjord, sulle strade 862 e 86, con brevi deviazioni per Husøy e Mefjordvær.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/', '2026-11-10'),
  ('NO-3', 'senja', 'it', 1, 'Sull''isola si arriva dal ponte di Finnsnes (dalla E6) oppure con i traghetti Botnhamn–Brensholmen (verso Tromsø) e Gryllefjord–Andenes (verso Andøya).', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/', '2026-11-10'),
  ('NO-3', 'senja', 'it', 2, 'Nelle aree di sosta i camper non possono svuotare le acque nere: i punti di scarico più vicini sono a Skaland, Senjahopen e Mefjordvær.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/', '2026-11-10'),
  ('NO-3', 'reinebringen', 'it', 0, 'Ai piedi del Reinebringen l''area di sosta Reinehalsen dà la vista su Reine e sul Reinefjord senza salire; è accessibile in sedia a rotelle.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/reinehalsen/', '2026-11-10'),
  ('NO-3', 'ramberg', 'it', 0, 'L''area di sosta ha servizi igienici aperti tutto l''anno.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/rambergstranda/', '2026-11-10'),
  ('NO-3', 'ramberg', 'it', 1, 'Una passerella stretta in traversine di legno porta alla spiaggia; l''area è accessibile in sedia a rotelle solo in parte.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/rambergstranda/', '2026-11-10'),
  ('NO-3', 'ramberg', 'it', 2, 'Qui i camper non possono svuotare le acque nere.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/rambergstranda/', '2026-11-10'),
  ('NO-3', 'eggum', 'it', 0, 'Parcheggio e servizi sono sul lato verso il mare; i servizi igienici sono aperti da inizio maggio a inizio ottobre.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/eggum/', '2026-11-10'),
  ('NO-3', 'eggum', 'it', 1, 'L''area di sosta è accessibile in sedia a rotelle (quindi anche con il passeggino).', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/eggum/', '2026-11-10'),
  ('NO-3', 'eggum', 'it', 2, 'Accanto al parcheggio c''è la scultura «Hode» di Markus Raetz, parte di Skulpturlandskap Nordland.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/eggum/', '2026-11-10'),
  ('NO-3', 'borg-lofoten', 'it', 0, 'Poco lontano, l''area di sosta Torvdalshalsen è su un''altura con la vista sulla campagna e sul museo vichingo di Borg; ha un lungo riparo con panche contro vento e pioggia.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/torvdalshalsen/', '2026-11-10'),
  ('NO-3', 'borg-lofoten', 'it', 1, 'A Torvdalshalsen i servizi igienici sono aperti tutto l''anno e i camper possono svuotare le acque nere in un impianto a parte; l''area è accessibile in sedia a rotelle.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/torvdalshalsen/', '2026-11-10'),
  ('NO-3', 'gimsoy', 'it', 0, 'Accanto al ponte sul Gimsøystraumen c''è un''area di sosta con parcheggio e servizi igienici aperti tutto l''anno, accessibile in sedia a rotelle.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/lofoten/gimsoystraumen/', '2026-11-10'),
  ('NO-3', 'bleik', 'it', 0, 'A nord di Bleik l''area di sosta Kleivodden, riparata ai piedi di pendii ripidi, guarda l''oceano e le scogliere degli uccelli di Bleiksøya; è accessibile in sedia a rotelle.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/andoya/kleivodden/', '2026-11-10'),
  ('NO-3', 'bleiksoya', 'it', 0, 'Le scogliere degli uccelli dell''isola si vedono da terra dall''area di sosta Kleivodden, a nord di Bleik.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/andoya/kleivodden/', '2026-11-10'),
  ('NO-3', 'spaceship-aurora', 'it', 0, 'A Børvågen la strada può restare chiusa fino a 8 ore durante le attività della base spaziale: da controllare prima di partire.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/andoya/', '2026-11-10'),
  ('NO-3', 'tungeneset', 'it', 0, 'La passerella e l''area di sosta sono accessibili in sedia a rotelle (quindi anche con il passeggino).', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/tungeneset/', '2026-11-10'),
  ('NO-3', 'tungeneset', 'it', 1, 'I servizi igienici sono aperti da inizio maggio a inizio ottobre.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/tungeneset/', '2026-11-10'),
  ('NO-3', 'tungeneset', 'it', 2, 'Qui i camper non possono svuotare le acque nere.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/tungeneset/', '2026-11-10'),
  ('NO-3', 'ersfjord-senja', 'it', 0, 'Sulla spiaggia c''è un edificio di servizio triangolare rivestito d''oro: i servizi igienici sono aperti da inizio maggio a inizio ottobre.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/ersfjordstranda/', '2026-11-10'),
  ('NO-3', 'ersfjord-senja', 'it', 1, 'L''area è accessibile in sedia a rotelle solo in parte.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/ersfjordstranda/', '2026-11-10'),
  ('NO-3', 'bergsbotn', 'it', 0, 'La piattaforma panoramica, lunga 44 metri, è accessibile in sedia a rotelle.', 'Nasjonale turistveger (Statens vegvesen)', 'https://www.nasjonaleturistveger.no/en/routes/senja/bergsbotn/', '2026-11-10');
